let nextId = 8000

export const additionalQuestions = questionGroups.flatMap(([sinf, bolim, items]) =>
  items.map(([mavzu, savol, answer, wrong1, wrong2, izoh], index) => {
    const togriJavob = (index + sinf + (bolim === 'jahon' ? 1 : 0)) % 3
    const variantlar = [wrong1, wrong2]
    variantlar.splice(togriJavob, 0, answer)

    return {
      id: nextId++,
      sinf,
      bolim,
      mavzu,
      qiyinlik: index % 5 === 0 ? 'qiyin' : index % 2 === 0 ? 'oson' : 'orta',
      savol,
      variantlar: variantlar.map((variant, optionIndex) => `${String.fromCharCode(65 + optionIndex)}) ${variant}`),
      togriJavob,
      izoh
    }
  })
)
